import { foods, createFoodDay, sampleDraft, nutrition, saveMeal, totals } from './food-state.js';
import { safe, icon, closeSheet, react } from './nap.js';
const $=s=>document.querySelector(s),fmt=v=>Math.round(v).toLocaleString('hu-HU');
let day=createFoodDay(),draft=null,stage='input',source='',callbacks;
const screen=document.createElement('section');screen.className='food-screen';screen.hidden=true;screen.setAttribute('aria-label','Étkezés logolása');$('.device').append(screen);
const button=(label,attr='',secondary=false)=>`<button class="food-action ${secondary?'secondary':''}" ${attr}>${label}</button>`;
const art=`<svg class="food-art" viewBox="0 0 300 170" aria-hidden="true"><defs><linearGradient id="food-cup" x2=".7" y2="1"><stop stop-color="#eaf4f4"/><stop offset=".5" stop-color="#9bbdc6"/><stop offset="1" stop-color="#355468"/></linearGradient><linearGradient id="food-banana" x2=".3" y2="1"><stop stop-color="#fff4ad"/><stop offset=".5" stop-color="#e1c566"/><stop offset="1" stop-color="#8b6537"/></linearGradient></defs><ellipse cx="150" cy="145" rx="100" ry="13" fill="#000" opacity=".25"/><g transform="rotate(-8 115 85)"><path d="M58 45L73 133Q112 151 149 132L165 45Z" fill="url(#food-cup)" stroke="#b3d4db"/><ellipse cx="111" cy="45" rx="54" ry="16" fill="#d9eaec" stroke="#91b3bc"/><ellipse cx="111" cy="45" rx="46" ry="11" fill="#f9f0db"/><path d="M76 78Q112 94 151 78L146 109Q113 125 81 109Z" fill="#4d767f"/><path d="M103 87L98 102 117 106 124 91Z" fill="#d5eaa6"/><path d="M73 57L83 75" stroke="#ffffff77" stroke-width="3" stroke-linecap="round"/></g><path d="M157 116C207 128 249 75 230 34L239 27C277 76 235 147 179 143Z" fill="url(#food-banana)" stroke="#e6c370" stroke-width="1.5"/><path d="M171 126C220 130 251 77 237 41" fill="none" stroke="#fff0a9" stroke-width="2"/><path d="M229 34L231 24 240 24 239 31" fill="#63583a"/></svg>`;
export function openFood(text=''){closeSheet();source=text;draft=null;stage='input';screen.hidden=false;$('.device').classList.add('in-food');if(text&&/joghurt/i.test(text)&&/banán/i.test(text)){draft=sampleDraft();stage='review';}render();}
function leave(){screen.hidden=true;$('.device').classList.remove('in-food');callbacks?.refresh();syncOverview();}
function render(){screen.innerHTML=`<div class="food-scroll"><header class="food-header"><button data-food-leave aria-label="Vissza a Fuel Mai oldalára">‹</button><span><small>FUEL · DEMÓ</small><strong>${stage==='saved'?'Étkezés rögzítve':'Együtt a tányér körül'}</strong></span>${icon('bowl')}</header><div class="food-steps"><span class="on">01 Mondd el</span><i></i><span class="${stage!=='input'?'on':''}">02 Pontosíts</span><i></i><span class="${stage==='saved'?'on':''}">03 Kész</span></div>${stage==='input'?inputView():stage==='review'?review():saved()}</div>`;screen.querySelector('.food-scroll').scrollTop=0;updatePreview();}
function inputView(){return `<div class="food-intro"><span class="overline">MEZO FIGYEL RÁD</span><h1>Mi esett jól?</h1><p>Mondd el a saját szavaiddal. Az adagokat utána együtt pontosítjuk.</p>${art}</div><form id="food-input-form"><label class="food-label">Az étkezésed<textarea name="meal" required placeholder="Egy joghurt és egy banán…">${safe(source)}</textarea></label><button type="button" class="sample-food" data-food-example>${icon('chat')} Kipróbálom: joghurt és banán ↗</button>${button('Nézzük meg együtt ✦','type="submit"')}<p id="food-input-error" role="alert"></p></form><p class="food-note">Működési demó: a joghurt–banán példát ismeri. Nincs hangrögzítés vagy valódi AI-elemzés.</p>`;}
function review(){return `<div class="food-intro"><span class="overline">FELISMERT TÉTELEK · MINTAELEMZÉS</span><h1>Két apróság.<br>Egy kis feltöltődés.</h1></div><div class="food-source">${icon('chat')}<p>${safe(source||'Joghurt és banán')}</p><button data-food-rewrite aria-label="Étkezés leírásának átírása">✎</button></div><div class="food-attention"><span>✦</span><p>A joghurt típusát nem tudom biztosan. Natúrral és becsült adagokkal indulunk — pontosítsd lent.</p></div><form id="food-review-form"><div class="food-item"><div class="food-item-head">${icon('bowl')}<span><small>01 · TEJTERMÉK</small><strong>Joghurt</strong></span><span class="estimate-pill">BECSÜLT</span></div><label class="food-label">Milyen joghurt?<select name="yogurt"><option value="yogurt" ${draft.items[0].key==='yogurt'?'selected':''}>Natúr joghurt</option><option value="greek" ${draft.items[0].key==='greek'?'selected':''}>Görög joghurt</option></select></label>${portion('yogurtGrams',draft.items[0].grams,'Joghurt mennyisége grammban','Egy pohár ≈ 150 g')}</div><div class="food-item"><div class="food-item-head">${icon('sun')}<span><small>02 · GYÜMÖLCS</small><strong>Banán</strong></span><span class="estimate-pill">BECSÜLT</span></div>${portion('bananaGrams',draft.items[1].grams,'Banán mennyisége grammban','Egy közepes darab ≈ 120 g, héj nélkül')}</div><label class="food-time">Mikor ettél?<input type="time" name="time" value="${safe(draft.time)}" required></label><section class="nutrition-preview" aria-label="Étkezés előnézete"><span class="overline">AZ ADAGJAIDDAL SZÁMOLVA</span><div id="food-preview"></div></section><div class="food-reading"><span class="overline">MEZO · MINTAÉRTÉKELÉS</span><p>Gyümölcs és joghurt egy gyors uzsonnához. A fehérje mennyiségét a választott joghurt és az adagja is alakítja.</p></div>${button('Rögzítem az étkezést ✓','type="submit"')}<p id="food-review-error" role="alert"></p><p class="food-note">Becsült mintaértékek, nem termékadatok. Csak mentéskor változik a napi összeg. Újratöltéskor a demó törlődik.</p></form>`;}
function portion(name,value,label,hint){return `<div class="portion"><span><small>ADAG</small><span class="portion-field"><button type="button" data-portion="${name}" data-delta="-10" aria-label="${label} csökkentése">−</button><input type="number" name="${name}" aria-label="${label}" min="1" max="2000" step="1" value="${value}" required><b>g</b><button type="button" data-portion="${name}" data-delta="10" aria-label="${label} növelése">+</button></span></span><small>${hint}</small></div>`;}
function readDraft(){const form=$('#food-review-form');if(!form||!draft)return;draft.items[0]={key:form.elements.yogurt.value,grams:Number(form.elements.yogurtGrams.value)};draft.items[1].grams=Number(form.elements.bananaGrams.value);draft.time=form.elements.time.value;}
function updatePreview(){const el=$('#food-preview');if(!el)return;readDraft();if(draft.items.some(i=>!Number.isFinite(i.grams)||i.grams<1||i.grams>2000)){el.textContent='Adj meg 1–2000 g közötti mennyiséget.';return;}const v=nutrition(draft);el.innerHTML=`<strong>${fmt(v.kcal)}<small>kcal</small></strong><div><span><b>${fmt(v.p)} g</b>fehérje</span><span><b>${fmt(v.c)} g</b>szénhidrát</span><span><b>${fmt(v.f)} g</b>zsír</span></div>`;}
function saved(){const v=nutrition(draft),t=totals(day);return `<div class="food-success"><div class="food-success-art">${icon('bowl')}<span>✓</span></div><span class="overline">A NAPOD RÉSZE LETT</span><h1>Megérkezett<br>az uzsonnád.</h1><p>${foods[draft.items[0].key].name} · banán<br>${draft.time} · ${fmt(v.kcal)} kcal</p><div class="saved-budget"><small>EDDIG MA</small><strong>${fmt(t.kcal)}<span> / 2 400 kcal</span></strong><div class="food-budget-bar"><i style="width:${Math.min(100,t.kcal/2400*100)}%"></i></div></div>${button('Megnézem a mai keretem →','data-food-done')}${button('Pontosítok még rajta','data-food-correct',true)}<p class="food-note">Mentve a demóban. Nincs valódi adatmentés.</p></div>`;}
function syncOverview(){const tile=document.querySelector('#tiles [data-open="fuel"]'),t=totals(day);if(tile){tile.querySelector('.tile-value').innerHTML=`${fmt(t.kcal)}<small>kcal</small>`;tile.querySelector('.tile-hint').textContent=`Eddig ma · ${fmt(t.p)} g fehérje`;}}
function timeline(){const entries=[{time:'08:00',name:'Zabkása gyümölccsel',hint:'Reggeli · mintaelőzmény',kcal:420},{time:'12:30',name:'Csirkés rizstál',hint:'Ebéd · mintaelőzmény',kcal:760},...day.meals.map(m=>({time:m.time,name:'Joghurt és banán',hint:`${m.items[0].grams} g + ${m.items[1].grams} g · pontosítható`,kcal:nutrition(m).kcal,id:m.id}))];return entries.sort((a,b)=>a.time.localeCompare(b.time)).map(m=>`<${m.id?'button':'div'} class="meal-entry ${m.id?'new-meal':''}" ${m.id?`data-food-edit="${m.id}"`:''}><span class="meal-time">${m.time}</span>${icon('bowl')}<span><strong>${m.name}</strong><small>${m.hint}</small></span><b>${fmt(m.kcal)}<small>kcal ${m.id?'↗':''}</small></b></${m.id?'button':'div'}>`).join('');}
export function foodContent(domain,page){if(domain!=='fuel'||page!==0)return null;const t=totals(day),remaining=2400-t.kcal;return `<div class="fuel-budget"><span class="overline">SZERDA · EDZÉSNAP</span><div class="budget-top"><span>Van még tér a napodban.</span>${icon('bowl')}</div><div class="budget-remaining"><strong>${fmt(Math.abs(remaining))}</strong><span>kcal ${remaining>=0?'a mai keretből':'a keret felett'}</span></div><div class="food-budget-bar"><i style="width:${Math.min(100,t.kcal/2400*100)}%"></i></div><div class="budget-caption"><span>${fmt(t.kcal)} kcal eddig</span><span>2 400 kcal keret</span></div><button class="budget-explain" data-food-budget>Mi alakítja a keretem? ↗</button></div><div class="fuel-macros">${[['p','Fehérje',160,'#bca6f1'],['c','Szénhidrát',270,'#d9c395'],['f','Zsír',76,'#8ed2e8']].map(([key,name,target,color])=>`<div style="--macro-color:${color}"><span>${name}</span><strong>${fmt(t[key])}<small> / ${target} g</small></strong><i><b style="width:${Math.min(100,t[key]/target*100)}%"></b></i></div>`).join('')}</div><button class="food-log-door" data-food>${icon('chat')}<span><strong>Mit ettél?</strong><small>Mondd Mezonak, és pontosítsuk együtt.</small></span><b>＋</b></button><div class="food-training">${icon('dumbbell')}<span><strong>Ma Felsőtest A</strong><small>A mozgásod már része a mintakeretnek.</small></span><button data-route="train/0" aria-label="Mai edzés megnyitása">↗</button></div><div class="food-list-heading"><h2>Ma a tányérodon</h2><span>${day.meals.length+2} ÉTKEZÉS</span></div><div class="food-timeline">${timeline()}</div><div class="food-next"><span class="overline">A NAP MÉG FOLYTATÓDIK</span><h3>Vacsoránál találkozunk.</h3><p>A mai étkezéseidet és a sportodat egy helyen követheted.</p><button data-route="fuel/1">Receptek és Receptműhely →</button></div><p class="food-note">Mintaadatok és becsült tápértékek. A rögzített uzsonna ténylegesen frissíti ezt a demót.</p>`;}
export function initFood(options){callbacks=options;document.addEventListener('mezo:day-render',syncOverview);document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;
 if(el.hasAttribute('data-food-leave'))leave();
 if(el.hasAttribute('data-food-example')){source='Egy joghurt és egy banán.';$('#food-input-form textarea').value=source;}
 if(el.hasAttribute('data-food-rewrite')){stage='input';render();}
 if(el.dataset.portion){const input=screen.querySelector(`[name="${el.dataset.portion}"]`);input.value=String(Math.max(1,Math.min(2000,Number(input.value)+Number(el.dataset.delta))));updatePreview();}
 if(el.hasAttribute('data-food-done')){leave();callbacks.go('fuel',0);}
 if(el.hasAttribute('data-food-correct')){draft=structuredClone(day.meals.find(m=>m.id===draft.id));stage='review';render();}
 if(el.dataset.foodEdit){draft=structuredClone(day.meals.find(m=>m.id===el.dataset.foodEdit));source='Joghurt és banán';stage='review';screen.hidden=false;$('.device').classList.add('in-food');render();}
 if(el.hasAttribute('data-food-budget'))callbacks.detail('A mai keret összeáll','A 2 400 kcal itt egy előre megadott edzésnapi mintakeret. Az éles appban a saját alapigényed, súlycélod és sportterved adja a számítás alapját. A demóban az új uzsonna a bevitt mennyiséget módosítja, a célt nem.');
 });
 document.addEventListener('input',e=>{if(e.target.closest('#food-review-form'))updatePreview();});
 document.addEventListener('change',e=>{if(e.target.closest('#food-review-form'))updatePreview();});
 document.addEventListener('submit',e=>{if(e.target.id==='food-input-form'){e.preventDefault();source=new FormData(e.target).get('meal').trim();if(!/joghurt/i.test(source)||!/banán/i.test(source)){$('#food-input-error').textContent='Ebben a demóban a joghurt és banán példát tudjuk elemezni. A mintamondattal végigpróbálhatod.';return;}const originalId=draft?.id;draft=sampleDraft();if(originalId)draft.id=originalId;stage='review';render();react('connect',2000);}if(e.target.id==='food-review-form'){e.preventDefault();readDraft();if(!saveMeal(day,draft)){$('#food-review-error').textContent='Ellenőrizd az adagokat és az időpontot.';return;}stage='saved';render();react('connect',2500);callbacks.refresh();syncOverview();}});
 $('#restart').addEventListener('click',()=>{day=createFoodDay();draft=null;leave();});
}

export const foodSnapshot=()=>({...totals(day)});
